// O(1) - no loops, no recursion scaling with n
const first = arr[0];

// O(log n) - input space halves each iteration
let lo = 0, hi = n - 1;
while (lo <= hi) {
  const mid = (lo + hi) >> 1;
  if (arr[mid] === target) return mid;
  else if (arr[mid] < target) lo = mid + 1;
  else hi = mid - 1;
}

