// O(n²) space warning - creating n×n matrix
const dp = Array.from({ length: n }, () => new Array(n).fill(0));

// O(log n) recursion stack space - binary search recursive
function bSearch(lo, hi) {
  if (lo > hi) return -1;
  const mid = (lo + hi) >> 1;
  // each call reduces problem to half
  return arr[mid] === target ? mid
    : arr[mid] < target ? bSearch(mid + 1, hi)
    : bSearch(lo, mid - 1);
}
